#include <stdio.h>
#include <stdlib.h>

long gcd(long a, long b) {
    if (b == 0) {
        return a;
    } else {
        return gcd(b, a % b);
    }
}

long lcm(long a, long b) {
    return (a * b) / gcd(a, b);
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("USAGE\n");
        return 0;
    }

    char *endptr;
    long num1 = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        printf("BAD_INPUT\n");
        return 0;
    }

    long num2 = strtol(argv[2], &endptr, 10);
    if (*endptr != '\0') {
        printf("BAD_INPUT\n");
        return 0;
    }

    if (num1 < 0 || num2 < 0) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }

    if (num1 > 1000000 || num2 > 1000000) {
        printf("OVERFLOW\n");
        return 0;
    }

    long g = gcd(num1, num2);
    long l = lcm(num1, num2);

    if (g == 0 && l == 0) {
        printf("gcd=0 lcm=0\n");
    } else {
        printf("gcd=%ld lcm=%ld\n", g, l);
    }

    return 0;
}
